import React from "react";
import {
  Breadcrumb,
  Row,
  Card,
  Descriptions,
  Typography,
  Empty,
  Button,
  Input,
  AutoComplete,
  Table,
} from "antd";
import {
  ProfileOutlined,
  HistoryOutlined,
  CommentOutlined,
  TagOutlined,
  PlusOutlined,
  SendOutlined,
  DownloadOutlined,
  DeleteOutlined,
} from "@ant-design/icons";
import { Link } from "react-router-dom";
import PageHeader from "components/layout-components/PageHeader";
import styled from "styled-components";
import moment from "moment-timezone";
// @ts-expect-error
import { AzureMP } from "react-azure-mp";
import { useQuery } from "@apollo/client";
import {
  Evidence,
  EvidenceArgs,
  EvidenceRes,
} from "graphql-src/evidence/queries";

const { Title, Text } = Typography;
const { TextArea } = Input;

const Details = styled(Card)`
  flex: 1;
  margin: 0;
`;
const Video = styled.div`
  flex: 1;
  max-width: 700px;
  border-radius: 10px;
  overflow: hidden;
`;
const VideoContainer = styled.div`
  display: flex;
  flex-direction: row;
  flex: 2;
  justify-content: center;
  margin-left: 30px;
`;
const TitleRow = styled.div`
  display: flex;
  flex-direction: row;
  align-items: center;
`;
const CommentRow = styled.div`
  display: flex;
  flex-direction: row;
  align-items: flex-end;
  flex: 1;
`;
const ContentRow = styled.div`
  display: flex;
  flex-direction: row;
`;
const Tags = styled(Card)`
  flex: 1;
  position: relative;
  overflow: hidden;
`;
const Comments = styled(Card)`
  flex: 2;
  margin-left: 30px;
  position: relative;
  overflow: hidden;
`;
const History = styled(Card)`
  flex: 1;
  position: relative;
  overflow: hidden;
`;
const CardOverlay = styled.div`
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: rgba(0, 0, 0, 0.5);
  z-index: 10;
  display: flex;
  align-items: center;
  justify-content: center;
`;

const Actions = styled.div`
  flex: 1;
  position: relative;
  overflow: hidden;
  margin-bottom: 0px;
  display: flex;
  justify-content: flex-end;
  margin-right: 70px;
`;

const EvidenceList = (props: any) => {
  const { data } = useQuery<EvidenceRes, EvidenceArgs>(Evidence, {
    variables: {
      groupId: props.match.params.id,
    },
  });

  console.log(data);

  return (
    <div>
      <PageHeader
        title="Evidence Details"
        display={true}
        breadcrumbs={
          <Breadcrumb>
            <Breadcrumb.Item>
              <Link to="/app/dashboard">Home</Link>
            </Breadcrumb.Item>
            <Breadcrumb.Item>
              <Link to="/app/evidence/list">Evidence Management</Link>
            </Breadcrumb.Item>
            <Breadcrumb.Item>Evidence Details</Breadcrumb.Item>
          </Breadcrumb>
        }
      />
      <Actions>
        <Card
          bodyStyle={{
            paddingTop: 5,
            paddingBottom: 5,
            minWidth: 340,
            display: "flex",
            justifyContent: "flex-end",
          }}
        >
          <Button
            type="primary"
            icon={<DownloadOutlined />}
            href={data?.demEvidence.fileUrl}
            target="_blank"
            download
          >
            Download
          </Button>
          <Button
            style={{ marginLeft: 10 }}
            type="primary"
            disabled
            danger
            icon={<DeleteOutlined />}
          >
            Delete
          </Button>
        </Card>
      </Actions>
      {data && (
        <ContentRow>
          <Details>
            <Row style={{ marginBottom: 10 }}>
              <ProfileOutlined style={{ fontSize: 20, marginRight: 10 }} />
              <Title level={4}>Details</Title>
            </Row>
            <Descriptions layout="horizontal" bordered column={1} size="middle">
              <Descriptions.Item label="Status">
                {data?.demEvidence.important ? "Important" : "Not Important"}
              </Descriptions.Item>
              <Descriptions.Item label="Device Name">
                {data?.demEvidence.officer.name}
              </Descriptions.Item>
              <Descriptions.Item label="Recorded At">
                {moment(data?.demEvidence.recordedAt)
                  .tz("Europe/London")
                  .format("HH:mm DD/MM/YY")}
              </Descriptions.Item>
              <Descriptions.Item label="Duration">
                {moment
                  .utc(data?.demEvidence.duration! * 1000)
                  .format("HH:mm:ss")}
              </Descriptions.Item>
              <Descriptions.Item label="Device S/N">
                {data?.demEvidence.deviceSn}
              </Descriptions.Item>
              {/* <Descriptions.Item label="Group">
                {data?.demEvidence.group.name}
              </Descriptions.Item> */}
            </Descriptions>
          </Details>
          <VideoContainer>
            <Video>
              <AzureMP
                skin="amp-flush"
                src={[
                  {
                    src: data?.demEvidence?.streamUrls.find(
                      ({ streamingProtocol }) => streamingProtocol === "Hls"
                    )?.paths[0],
                    type: "application/vnd.ms-sstr+xml",
                  },
                ]}
              />
            </Video>
          </VideoContainer>
        </ContentRow>
      )}
      <ContentRow style={{ marginTop: 30, marginBottom: 10 }}>
        <Tags>
          <CardOverlay>
            <Title style={{ color: "#fff" }} level={4}>
              Tags coming soon...
            </Title>
          </CardOverlay>
          <TitleRow style={{ marginBottom: 10 }}>
            <TagOutlined style={{ fontSize: 20, marginRight: 10 }} />
            <Title style={{ margin: 0, marginRight: 20 }} level={4}>
              Tags
            </Title>
            <CommentRow>
              <AutoComplete
                options={[
                  { value: "test", key: 1 },
                  { value: "test2", key: 2 },
                ]}
                style={{ flex: 1 }}
                onSelect={(e) => console.log(e)}
                onSearch={(e) => console.log(e)}
                placeholder="Violence, Incident..."
                filterOption={(inputValue, option) =>
                  option!.value
                    .toUpperCase()
                    .indexOf(inputValue.toUpperCase()) !== -1
                }
                allowClear
              />
              <Button
                shape="circle"
                style={{ marginLeft: 10 }}
                size="small"
                type="primary"
                icon={<PlusOutlined />}
              />
            </CommentRow>
          </TitleRow>
          <Empty
            description="This evidence has no tags."
            image={Empty.PRESENTED_IMAGE_SIMPLE}
          />
        </Tags>
        <Comments>
          <CardOverlay>
            <Title style={{ color: "#fff" }} level={4}>
              Comments coming soon...
            </Title>
          </CardOverlay>
          <Row style={{ marginBottom: 10 }}>
            <CommentOutlined style={{ fontSize: 20, marginRight: 10 }} />
            <Title level={4}>Comments</Title>
          </Row>
          <Empty
            description="There are no comments yet."
            image={Empty.PRESENTED_IMAGE_SIMPLE}
          />
          <Text strong>New Comment</Text>
          <CommentRow>
            <TextArea rows={2} style={{ marginRight: 10, marginTop: 5 }} />
            <Button size="small" type="primary" icon={<SendOutlined />}>
              Add
            </Button>
          </CommentRow>
        </Comments>
      </ContentRow>
      <History>
        <Row style={{ marginBottom: 10 }}>
          <HistoryOutlined style={{ fontSize: 20, marginRight: 10 }} />
          <Title level={4}>Evidence History</Title>
        </Row>
        <Table
          columns={[
            {
              title: "Date",
              dataIndex: "date",
              key: "date",
            },
            {
              title: "Action",
              dataIndex: "action",
              key: "action",
            },
            {
              title: "User",
              dataIndex: "user",
              key: "user",
            },
          ]}
          dataSource={data?.demEvidence.actions.map(
            ({ date, byUser, type }) => ({
              date: moment(date)
                .tz("Europe/London")
                .format("HH:mm DD/MM/YY"),
              action: type === "VIEW_EVIDENCE" ? "Viewed Evidence" : "",
              user: byUser.name,
            })
          )}
          loading={!data}
        />
      </History>
    </div>
  );
};

export default EvidenceList;
