import { gql } from '@apollo/client'

export const Evidence = gql`
  query demEvidence(
    $groupId: String!
  ) {
    demEvidence (where: { id: $groupId }) {
      id
      streamUrls {
        id
        streamingProtocol
        paths
      }
      duration
      officer {
        name
      }
      deviceSn
      recordedAt
      important
      fileUrl
      actions {
        id
        type
        date
        byUser {
          id
          name
        }
      }
    }
  }
`

export interface EvidenceArgs {
  groupId: string;
}

export interface EvidenceRes {
  demEvidence: {
    id: string;
    streamUrls: {
      id: string
      streamingProtocol: string;
      paths: string;
    }[]
    duration: number;
    officer: {
      name: string;
    };
    deviceSn: string;
    recordedAt: string;
    important: boolean;
    fileUrl: string;
    actions: {
      id: string;
      type: string;
      date: string;
      byUser: {
        id: string;
        name: string;
      }
    }[]
  }
}